auto* add = new QAction(QStringLiteral("Add note"), this);
add->setShortcut(QKeySequence(QStringLiteral("Ctrl+N")));
auto* clear = new QAction(QStringLiteral("Clear notes"), this);
clear->setEnabled(false);
auto* details = new QAction(QStringLiteral("Show details"), this);
details->setCheckable(true);
const auto updateCount = [list, clear, status]() {
    const int count = list->model()->rowCount();
    clear->setEnabled(count > 0);
    status->setText(count == 1 ? QStringLiteral("1 note") : QStringLiteral("%1 notes").arg(count));
};
const QStringList locations{QStringLiteral("Home"), QStringLiteral("Inbox"), QStringLiteral("Documents"), QStringLiteral("Folders")};
const QStringList glyphs{Typography::Icons::Home, Typography::Icons::Mail, Typography::Icons::Document, Typography::Icons::Folder};
const QStringList keys{QStringLiteral("Ctrl+H"), QStringLiteral("Ctrl+I"), QStringLiteral("Ctrl+D"), QStringLiteral("Ctrl+F")};
for (int i = 0; i < locations.size(); ++i) {
    auto* model = i == 0 ? notes : new QStringListModel(QStringList{locations.at(i) + QStringLiteral(" note")}, this);
    auto* navigate = new QAction(locations.at(i), this);
    navigate->setShortcut(QKeySequence(keys.at(i)));
    setActionGlyph(navigate, glyphs.at(i));
    palette->addCommand(navigate, QStringLiteral("Navigation"));
    menu->addAction(navigate);
    QObject::connect(model, &QAbstractItemModel::modelReset, this, updateCount);
    QObject::connect(navigate, &QAction::triggered, this, [list, location, model, navigate, updateCount]() {
        list->setModel(model);
        location->setText(navigate->text());
        updateCount();
    });
}
menu->addSeparator();
palette->addCommand(add, QStringLiteral("Notes"), {QStringLiteral("new"), QStringLiteral("create")});
palette->addCommand(clear, QStringLiteral("Notes"),
    {QStringLiteral("delete"), QStringLiteral("remove")});
palette->addCommand(details, QStringLiteral("View"),
    {QStringLiteral("count"), QStringLiteral("properties")});
setActionGlyph(add, Typography::Icons::Add);
setActionGlyph(clear, Typography::Icons::Delete);
setActionGlyph(details, Typography::Icons::Info);
QObject::connect(add, &QAction::triggered, list, [list]() {
    auto* notes = qobject_cast<QStringListModel*>(list->model());
    QStringList items = notes->stringList();
    items.append(QStringLiteral("Note %1").arg(items.size() + 1));
    notes->setStringList(items);
});
QObject::connect(clear, &QAction::triggered, list, [list]() {
    qobject_cast<QStringListModel*>(list->model())->setStringList({});
});
